WITH filtered AS (SELECT *, ROUND(stock_qty, 1) AS stock_qty_rounded, COALESCE(brand, 'OTHER') AS brand_clean FROM products WHERE launch_date >= DATE '2023-05-03') SELECT category, DATE_TRUNC('MONTH', launch_date) AS activity_month, COUNT(*) FILTER (WHERE category = 'Grocery') AS grocery_rows, ROUND(AVG(stock_qty_rounded), 2) AS avg_stock_qty_rounded, CORR(stock_qty, cost) AS corr_stock_qty_cost FROM filtered GROUP BY category, DATE_TRUNC('MONTH', launch_date) HAVING ROUND(AVG(stock_qty_rounded), 2) >= 0 ORDER BY avg_stock_qty_rounded
